const query = $json.query ?? {};
const supportedFlowTypes = new Set(['review', 'compliance', 'document', 'tests', 'batch', 'pull_request_review', 'pull_request_tests']);
const supportedStatuses = new Set(['pending', 'success', 'failed']);
function optionalText(value, field) { if (value === undefined || value === null) return null; const text = String(value).trim(); if (!text) throw new Error(`Query invalida para historico: ${field} nao pode ser vazio.`); return text; }
function optionalDate(value, field) { const text = optionalText(value, field); if (text === null) return null; const timestamp = Date.parse(text); if (Number.isNaN(timestamp)) throw new Error(`Query invalida para historico: ${field} deve ser uma data valida.`); return new Date(timestamp).toISOString(); }
function optionalBoolean(value) { if (value === undefined || value === null) return null; if (value === true || value === 'true') return true; if (value === false || value === 'false') return false; throw new Error('Query invalida para historico: cache_hit deve ser true ou false.'); }
const rawLimit = query.limit === undefined ? 20 : Number(query.limit);
if (!Number.isInteger(rawLimit) || rawLimit < 1 || rawLimit > 100) throw new Error('Query invalida para historico: limit deve ser um inteiro entre 1 e 100.');
const cursor = optionalText(query.cursor, 'cursor');
const flowType = optionalText(query.flow_type, 'flow_type');
const status = optionalText(query.status, 'status');
const model = optionalText(query.model, 'model');
const from = optionalDate(query.from, 'from');
const to = optionalDate(query.to, 'to');
const cacheHit = optionalBoolean(query.cache_hit);
if (flowType !== null && !supportedFlowTypes.has(flowType)) throw new Error('Query invalida para historico: flow_type nao suportado.');
if (status !== null && !supportedStatuses.has(status)) throw new Error('Query invalida para historico: status nao suportado.');
return [{ json: { limit: rawLimit, query_parameters: [rawLimit + 1, cursor, flowType, status, model, from, to, cacheHit] } }];

const request = $('Validate History List Query').first().json;
const rows = Array.isArray($json.items) ? $json.items : [];
const formatter = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23', timeZoneName: 'longOffset' });
function toSaoPauloIso(value) { const date = new Date(value); if (Number.isNaN(date.getTime())) return String(value); const parts = Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value])); return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}${parts.timeZoneName.replace('GMT', '')}`; }
const items = rows.slice(0, request.limit).map((item) => ({ ...item, timestamp: toSaoPauloIso(item.timestamp) }));
return [{ json: { items, page: { limit: request.limit, next_cursor: rows.length > request.limit && items.length > 0 ? items[items.length - 1].id : null } } }];
